'use strict';
const KEY='leadership-growth-v1';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data={step:0,fields:{},route:'',caseType:'',visited:[],prefs:{large:false,contrast:false}},saveOK=true;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&typeof saved==='object'&&saved.fields&&typeof saved.fields==='object'){data={...data,...saved};data.step=Number.isInteger(data.step)&&data.step>=0&&data.step<=7?data.step:0;data.visited=Array.isArray(data.visited)?data.visited:[];data.prefs=data.prefs||{};}}catch(e){saveOK=false;}
const steps=[{name:'המקרה שלי',sub:'6 דקות · אישי',page:1},{name:'תשומת הלב',sub:'8 דקות · מיפוי',page:2},{name:'הדפוס שלי',sub:'14 דקות · בזוגות',page:3},{name:'שיחה אחרת',sub:'16 דקות · תרגול',page:4},{name:'הבחירה שלי',sub:'12 דקות · החלטה',page:5},{name:'הצעד הבא',sub:'4 דקות · סיכום',page:7}];
const routes=[
{id:'expertise',name:'העמקת מומחיות',need:'יש צורך ביכולת מקצועית מוגדרת',action:'הדגמה, תרגול, התנסות ומשוב סביב משימה אמיתית.',example:'לתרגל פתיחה של שיחת הורים מורכבת, להתנסות בשיחה ולחזור למשוב.',ask:'איזו פעולה מקצועית נרצה שתוכל לבצע טוב יותר? ומה יעזור לה ללמוד אותה?'},
{id:'autonomy',name:'אוטונומיה ויוזמה',need:'יש מקום להרחיב שיקול דעת והשפעה',action:'להעביר החלטה מוגדרת, עם סמכות, גבולות ותמיכה.',example:'להגדיר סוג של פניות הורים שבו המחנכת מחליטה בעצמה, ומתי מתייעצים.',ask:'איזו החלטה יכולה לעבור אליה? מה חייב להיות ברור לפני כן?'},
{id:'team',name:'מסוגלות צוותית',need:'יש ידע בצוות שאפשר ללמוד ממנו יחד',action:'לבחון קושי משותף, לנסות דרך פעולה ולחזור לבדיקה.',example:'שתי מחנכות בוחנות עבודות תלמידים ומתכננות יחד שינוי בהוראה.',ask:'מה תוכלנה ללמוד יחד, ואיזה זמן משותף יהיה לרשותן?'},
{id:'wellbeing',name:'מניעת שחיקה',need:'צריך לפנות מקום כדי שאפשר יהיה להמשיך',action:'להסיר דרישה, לשנות חלוקת אחריות או ליצור תמיכה קבועה.',example:'להעביר אחריות על אירוע למחנכת אחרת עם ליווי, ולצמצם דיווח כפול.',ask:'איזו דרישה אפשר לצמצם, ועל מי ייפול העומס אם נעביר אותה?'},
{id:'direction',name:'כיוון והתפתחות אישית',need:'צריך לברר מה המחנכת רוצה לעצמה',action:'לקיים שיחת כיוון ולבחור התנסות קטנה לפני התחייבות לתפקיד.',example:'לבחון יחד הנחיית מפגש עמיתות אחד לפני קבלת אחריות שנתית.',ask:'מה היא רוצה להעמיק? איזו התנסות קטנה תעזור לה לבדוק את הכיוון?'}
];
const mapNames=['אחריות נוספת','זמן לחשוב ולהתייעץ','משוב שעזר להתקדם','אפשרות להחליט','הקלה בעומס'];
const phases=[['תיאור הרקע',1,'ספרי לעמיתה מה קרה, מה כבר ידוע ומה חשוב לך לברר.'],['שיחה ראשונה',2,'פתחי את השיחה כפי שהיית פותחת אותה בעבודה. העמיתה מגיבה כמחנכת לפי הרקע שקיבלה.'],['משוב',1,'העמיתה משלימה: הבנתי שאת מצפה ממני ל… השאלה אפשרה לי לומר… נשאר לי לא ברור…'],['ניסיון נוסף',2,'בחרי שינוי אחד: שאלה אחרת, פחות הסברים, ציפייה ברורה יותר או הקשבה לתשובה לא נוחה.'],['מה אקח איתי',2,'כתבי משפט אחד שתרצי לומר ושאלה אחת שתרצי לשאול בשיחה האמיתית.']];
let timer={phase:0,left:60,running:false,end:0},tickId;
function notify(msg){$('#toast').textContent=msg;$('#toast').hidden=false;clearTimeout(notify.id);notify.id=setTimeout(()=>$('#toast').hidden=true,4000);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));saveOK=true;}catch(e){saveOK=false;}const message=saveOK?'נשמר במכשיר שלך':'השמירה אינה זמינה';if($('#save-status').textContent!==message)$('#save-status').textContent=message;}
function field(id,label,placeholder='',hint='',type='textarea'){const val=data.fields[id]||'';return `<div class="field"><label for="${id}">${label}</label>${hint?`<p class="hint" id="${id}-hint">${hint}</p>`:''}${type==='textarea'?`<textarea id="${id}" data-field="${id}" rows="3" placeholder="${esc(placeholder)}" ${hint?`aria-describedby="${id}-hint"`:''}>${esc(val)}</textarea>`:`<input id="${id}" data-field="${id}" type="${type}" value="${esc(val)}" placeholder="${esc(placeholder)}" ${hint?`aria-describedby="${id}-hint"`:''}>`}</div>`;}
function charFig(name,cls=''){return `<figure class="char ${cls}" aria-hidden="true"><img src="assets/char-${name}.webp" alt="" width="506" height="279" loading="lazy"></figure>`;}
function head(n,title,desc,badges,char){return `<div class="flow-dots" aria-hidden="true">${steps.map((_,i)=>`<span class="${i<n?'on':''}"></span>`).join('')}</div><div class="head-wrap"><div class="head-text"><div class="eyebrow">תחנה ${n} מתוך 6</div><h1>${title}</h1><p class="intro-text">${desc}</p><div class="badges">${badges.map(b=>`<span class="badge">${b}</span>`).join('')}</div></div>${char?charFig(char):''}</div>`;}
function nav(nextLabel='ממשיכות לשלב הבא',next=data.step+1){return `<div class="nav-actions"><button class="secondary" data-go="${data.step-1}">→ חזרה</button><button class="primary" data-go="${next}">${nextLabel}<span aria-hidden="true">←</span></button></div><p class="quiet" style="margin-top:12px">אפשר להמשיך גם בלי למלא הכול. תמיד אפשר לחזור.</p>`;}
function reminder(){return data.fields.event?`<details class="details"><summary>להיזכר במקרה שבחרתי</summary><div class="case-reminder">${esc(data.fields.event)}</div></details>`:'';}
function panel(content,cls=''){return `<section class="panel ${cls}">${content}</section>`;}
function selectedRoute(){return routes.find(r=>r.id===data.route);}
function summaryRows(){return [['עם מי אברר את המהלך?',data.fields.withWho],['מה נרצה שיוכלו לעשות או להחליט אחרת?',data.fields.change],['למה זה חשוב בעבודה החינוכית?',data.fields.why],['דרך הלמידה או התמיכה',data.fields.method],['מה אני מתחייבת לאפשר?',data.fields.commitment],['מה אצמצם או אפנה?',data.fields.reduce],['מה פתוח לבחירת המחנכת?',data.fields.choice],['אם יהיה קושי, לפני שאקח בחזרה…',data.fields.ifThen],['מה נבדוק בעוד חודש?',data.fields.evidence],['מועד השיחה הראשונה',data.fields.firstDate],['מועד הבדיקה המשותפת',data.fields.reviewDate]];}
function rowsHTML(){return `<dl>${summaryRows().map(([label,value])=>`<div class="summary-row"><dt>${label}</dt><dd>${value?esc(value):'<span class="empty">פתוח להשלמה בשיחה</span>'}</dd></div>`).join('')}</dl>`;}
function planHTML(){const r=selectedRoute();return `<div class="print-logos"><img src="assets/logo-haifa.png" alt="עיריית חיפה · מינהל חינוך, תרבות וספורט"><img src="assets/logo-reshit.png" alt="ראשית · קהילות מחנכות"></div><h1>כרטיס ההחלטה שלי</h1><p>מראה פנימית · מה אני מחזיקה — ומה יכול לצמוח?</p><h2>${r?esc(r.name):'המסלול עדיין פתוח לבחירה'}</h2>${rowsHTML()}`;}
function render(){
 document.body.classList.toggle('large-text',!!data.prefs.large);document.body.classList.toggle('high-contrast',!!data.prefs.contrast);
 const active=data.step===6?4:data.step===7?5:data.step-1;
 $('#steps').innerHTML=steps.map((s,i)=>`<button class="step-link ${active===i?'active':''}" data-go="${s.page}" ${active===i?'aria-current="step"':''}><span class="step-number">${i+1}</span><span>${s.name}<small>${s.sub}</small></span></button>`).join('');
 let html='';
 if(data.step===0){const has=Object.values(data.fields).some(v=>String(v).trim())||data.route||data.caseType;html=`<section class="welcome"><div class="welcome-main"><div class="eyebrow">מחברת למידה למנהלות</div><h1>מה אני מחזיקה —<br><span>ומה יכול לצמוח?</span></h1><p class="intro-text welcome-description">מרחב לעצור לרגע, להתבונן במקרה מהעבודה ולבחור צעד שיאפשר לך ולצוות להתפתח.</p><div class="badges"><span class="badge">6 תחנות</span><span class="badge">שעה אחת במפגש</span><span class="badge">בקצב שלך</span></div><div class="welcome-actions"><button class="primary" data-go="${has?(data.lastStep||1):1}">${has?'ממשיכות מהמקום שבו עצרתי':'מתחילות ממקרה אחד'} <span aria-hidden="true">←</span></button>${has?'<button class="text-button" data-action="reset">פתיחת תהליך חדש</button>':''}</div><p class="privacy-note">הכתיבה נשמרת רק בדפדפן הזה. היא אינה נשלחת למנחה או למנהלות אחרות. מומלץ להשתמש בראשי תיבות. בסיום תוכלי להוריד רק את כרטיס ההחלטה.</p>${!saveOK?'<p class="callout">השמירה בדפדפן אינה זמינה כרגע. אפשר לעבוד ולהוריד גיבוי לפני היציאה.</p>':''}</div>${charFig('umbrella','char-hero')}<div class="journey-preview"><div><b>01 / להתבונן</b><strong>להתחיל במה שקרה</strong><p>מקרה אחד ומפת תשומת הלב שלך.</p></div><div><b>02 / להתנסות</b><strong>לפתוח אפשרות אחרת</strong><p>לזהות דפוס ולתרגל שיחה בזוגות.</p></div><div><b>03 / לבחור</b><strong>לפנות מקום לצמיחה</strong><p>מהלך אחד, התחייבות ומועד לחזרה.</p></div></div></section>`;}
 if(data.step===1){html=head(1,'מתחילות במה שקרה','בחרי מקרה מהחודש האחרון שילווה אותך לאורך התהליך. משהו קטן וממשי שממשיך להעסיק אותך.',['6 דקות','כתיבה אישית'],'net');const types=['לקחתי בחזרה משימה שהעברתי','פניתי שוב למי שאני תמיד סומכת עליה','הצעתי הזדמנות וקיבלתי סירוב','דחיתי שיחה שצריך לקיים','מקרה אחר שמעסיק אותי'];html+=`<p class="section-label">מה הכי קרוב למקרה שלך? אפשר לבחור ולשנות.</p><div class="choice-grid">${types.map(t=>`<button class="choice" data-case="${esc(t)}" aria-pressed="${data.caseType===t}"><strong>${t}</strong></button>`).join('')}</div>`;html+=panel(field('event','מה קרה?','תארי את האירוע בכמה משפטים.','ראשי תיבות מספיקים. אין צורך בשמות מלאים.')+field('myAction','מה עשיתי?','מה אמרתי או עשיתי באותו רגע?')+field('herAction','מה המחנכת אמרה או עשתה?','מה ראיתי ושמעתי בפועל?')+field('ending','איך הסתיים האירוע?','מה קרה מיד אחר כך?'));html+=`<div class="callout"><strong>עובדה לפני פרשנות</strong><p>״היא לא הגיעה לשתי פגישות״ הוא מידע שאפשר לברר. ״היא לא מחויבת״ הוא פירוש.</p></div>`+nav();}
 if(data.step===2){html=head(2,'מי מקבלת ממני מה?','התבונני בחודש האחרון. למי נתת אחריות, זמן, משוב, אפשרות להחליט או הקלה?',['8 דקות','מיפוי אישי','מותר להשאיר ריק'],'binoculars-bike');html+=panel(mapNames.map((name,i)=>`<div class="map-row"><h3>${name}</h3><div class="pair">${field('mapWho'+i,'למי?','ראשי תיבות','','text')}${field('mapExample'+i,'דוגמה ממשית','מה נתתי בפועל?','','text')}</div></div>`).join(''));html+=`<details class="details" open><summary>מבט נוסף על המפה</summary><ul class="prompt-list"><li>מי מקבלת אחריות, אבל מעט תמיכה?</li><li>מי מקבלת עזרה, אבל כמעט אינה מקבלת אפשרות להחליט?</li><li>מי עצמאית כל כך, שכמעט אינני פוגשת אותה?</li><li><strong>מי צריכה להסתבך כדי לקבל ממני זמן?</strong></li></ul></details>`+panel(field('mapInsight','ממצא אחד שקשור למקרה שלי','מה בולט לי, ומה הוא גורם לי לשאול?'))+nav();}
 if(data.step===3){html=head(3,'מה ממשיך את אותו מצב?','עובדות, פרשנות, תגובה והמשך. נסי לראות את המעגל, ולהשאיר מקום להסבר נוסף.',['14 דקות בזוגות','7 דקות לכל משתתפת'],'flashlight');html+=reminder();html+=panel(field('interpretation','1. מה הסקתי מההתנהגות שלה?','איזו משמעות נתתי למה שקרה?')+field('response','2. מה עשיתי בעקבות המסקנה?','איך הגבתי?')+field('reinforcement','3. מה קרה אחר כך?','האם ההמשך חיזק את המסקנה המקורית שלי?')+field('unknown','4. מה אני עדיין לא יודעת?','מה צריך לשאול, במקום להניח?'));html+=`<details class="details" open><summary>שלוש שאלות שהעמיתה שואלת</summary><ol class="prompt-list"><li>מה חשוב לך לשמור כאן?</li><li>מה את חוששת שיקרה אם תגיבי אחרת?</li><li>איזה הסבר נוסף להתנהגות המחנכת ראוי לבדוק?</li></ol></details>`+panel(field('protect','מה אני מנסה לשמור?','איכות, אמון ההורים, שקט בצוות, הוגנות…')+field('fear','מה יהיה לי קשה אם אפעל אחרת?','אפשר להשאיר את התשובה הזאת לעצמי.')+field('alternative','איזה הסבר נוסף ראוי לבדוק?','זו אפשרות לבירור, לא מסקנה על המחנכת.'))+`<details class="details"><summary>אם מתאים לי להעמיק</summary><p><strong>אם היא תוכל להסתדר טוב יותר בלעדיי, מה ארוויח — ומה עשוי להיות לי קשה בכך?</strong></p>${field('deeper','מחשבה אישית, לבחירתי','רק אם מתאים לך לכתוב כאן.')}</details>`+panel(field('clarify','הדבר שצריך לברר עם המחנכת הוא…','שאלה אחת שאקח לשיחה.'))+nav('ממשיכות לתרגול השיחה');}
 if(data.step===4){html=head(4,'שיחה שבה משהו יכול להשתנות','תרגלו בזוגות את השיחה הקשורה למקרה. לכל אחת 8 דקות — ניסיון, משוב וניסיון נוסף.',['16 דקות בזוגות','אפשר גם להתכונן לבד'],'ball');html+=reminder()+`<div class="callout">העמיתה מציעה תגובה אפשרית לפי הרקע שנתת. התרגול אינו מלמד מה המחנכת האמיתית חושבת.</div><section class="panel"><h2 class="panel-title">8 דקות לתרגול שלך</h2><div class="phase-tabs" aria-label="חלקי התרגול">${phases.map((p,i)=>`<button data-phase="${i}" class="${timer.phase===i?'active':''}" aria-pressed="${timer.phase===i}">${i+1}. ${p[0]} · ${p[1]} דק׳</button>`).join('')}</div><p class="phase-description" id="phase-description">${phases[timer.phase][2]}</p><div class="timer"><div><span class="timer-label" id="timer-label">${phases[timer.phase][0]}</span><strong class="timer-clock" id="clock" aria-label="זמן שנותר">${clock()}</strong></div><div class="timer-actions"><button id="timer-toggle">${timer.running?'השהיה':'הפעלת שעון'}</button><button id="timer-reset" aria-label="איפוס הזמן של חלק התרגול הנוכחי">איפוס</button></div></div><p class="quiet" id="timer-note">השעון לבחירתכן. בסיום כל חלק עוברים לחלק הבא בלחיצה.</p></section>`;html+=`<details class="details" open><summary>ארבע משימות לשיחה</summary><ol class="prompt-list"><li><strong>לתאר מצב:</strong> ״בשלוש הפעמים האחרונות ביקשת שאאשר לפני שפעלת.״</li><li><strong>ציפייה והכרה בחלקי:</strong> ״חשוב לי שתוכלי להחליט. ייתכן שלא הבהרתי מה בסמכותך.״</li><li><strong>לברר:</strong> ״מה גורם לך לעצור ולהעביר אליי את ההחלטה?״</li><li><strong>לבנות צעד יחד:</strong> ״איזו הכנה תעזור לך להחליט בעצמך במצבים האלה?״</li></ol></details>`+panel(field('opening','איך אפתח את השיחה?','תיאור קצר של המצב, הציפייה שלי והחלק שלי.')+field('question','מה ארצה לשאול?','שאלה שאינני יודעת עדיין את התשובה עליה.'))+`<details class="details"><summary>המשוב שהעמיתה נותנת</summary><ul class="prompt-list"><li>״הבנתי שאת מצפה ממני ל…״</li><li>״השאלה שלך אפשרה לי לומר…״</li><li>״נשאר לי לא ברור…״</li></ul></details>`+panel(field('feedback','מה למדתי מהמשוב?','מה נשמע אחרת מכפי שהתכוונתי?')+field('tryAgain','מה אשנה בניסיון השני?','שאלה אחרת, פחות הסברים, ציפייה ברורה או הקשבה לתשובה לא נוחה.')+field('takeaway','משפט אחד שאקח לשיחה האמיתית','מה אני רוצה לזכור לומר?'))+nav('ממשיכות לבחירת מהלך');}
 if(data.step===5){html=head(5,'איזו התפתחות נחוצה כאן?','בחרי מסלול מרכזי אחד שמתאים למה שגילית. זו הצעה לבירור עם המחנכת, ואפשר לשנות אותה.',['בחירה ותוכנית · 12 דקות','מסלול אחד להתחלה'],'overalls');html+=reminder();if(data.fields.clarify)html+=`<div class="case-reminder"><strong>השאלה שרציתי לברר</strong>${esc(data.fields.clarify)}</div>`;html+=`<div class="choice-grid">${routes.map((r,i)=>`<button class="choice" data-route="${r.id}" aria-pressed="${data.route===r.id}"><small>0${i+1}</small><strong>${r.name}</strong><small>${r.need}</small></button>`).join('')}</div>`;const r=selectedRoute();html+=`<div id="route-detail">${r?panel(`<div class="eyebrow">כיוון אפשרי לפעולה</div><h2>${r.action}</h2><p>${r.example}</p><p><strong>${r.ask}</strong></p>`,'soft'):'<p class="quiet" style="margin-top:18px">לחצי על מסלול כדי לראות פעולה אפשרית ושאלה לבירור.</p>'}</div>`+nav('בונות את כרטיס ההחלטה',6);}
 if(data.step===6){html=head(5,'בחירה שיש לה מקום בשבוע','הפכי את הכיוון למהלך קטן שאפשר לקיים. מה תציעי, מה תאפשרי ומה עדיין פתוח לשיחה?',['כרטיס החלטה','אפשר להשלים עם המחנכת'],'hoodie');const r=selectedRoute();html+=`<div class="case-reminder"><strong>${r?`המסלול שבחרתי: ${r.name}`:'עדיין לא בחרתי מסלול'}</strong><button class="text-button" data-go="5">בחירת מסלול או שינוי הבחירה</button></div>`;html+=panel(field('withWho','עם מי אברר את המהלך?','מחנכת או קבוצה קטנה — בראשי תיבות.','','text')+field('change','מה נרצה שיוכלו לעשות או להחליט אחרת?','יכולת או שינוי שאפשר לראות בעבודה.')+field('why','למה זה חשוב בעבודה החינוכית?','איך זה קשור לתלמידים, להוראה או לתפקוד הצוות?')+field('method','מה תהיה דרך הלמידה או התמיכה?',r?r.action:'איזו פעולה נקיים בפועל?'))+panel(field('commitment','מה אני מתחייבת לאפשר?','זמן, סמכות, משאב, ליווי או הפחתת עומס.')+field('reduce','מה אצמצם או אפנה כדי שזה יקרה?','מה יפסיק, יקטן או יעבור — ולמי?')+field('choice','מה עדיין פתוח לבחירת המחנכת?','על מה יש לה השפעה אמיתית?'))+`<details class="details" open><summary>בדיקת מציאות עם העמיתה</summary><ul class="prompt-list"><li>איפה בדיוק זה נכנס בשבוע העבודה?</li><li>מה תעשי אם התוצאה הראשונה תהיה פחות טובה מהמצופה?</li><li>מה יגרום לך לשנות את התוכנית?</li></ul></details>`+panel(field('ifThen','אם יהיה קושי, לפני שאקח את המשימה בחזרה…','אם יקרה ___, אעשה תחילה ___.')+field('evidence','מה נבדוק בעוד חודש?','עדות אחת להתקדמות, וגם בדיקה של העומס.')+`<div class="pair">${field('firstDate','מועד לשיחה הראשונה','','','date')}${field('reviewDate','מועד לבדיקה משותפת','','','date')}</div>`)+nav('לכרטיס ההחלטה שלי',7);}
 if(data.step===7){const r=selectedRoute();html=head(6,'מחשבה שהופכת לצעד','זה כרטיס ההחלטה שלך. אפשר לערוך, לשמור כ־PDF או להדפיס, ולהשלים יחד עם המחנכת.',['4 דקות לסיום','חוזרות לבדיקה בעוד חודש'],'icecream');html+=`<section class="summary-hero"><div class="eyebrow">הבחירה שלי</div><h2>${r?esc(r.name):'המסלול שלי עדיין פתוח'}</h2><p>${data.fields.change?esc(data.fields.change):'מה נרצה שיתאפשר? אפשר לחזור ולנסח את השינוי המבוקש.'}</p></section><div class="export-actions"><button class="primary" data-action="print">שמירת כרטיס ההחלטה כ־PDF ↓</button><button class="secondary" data-action="download">הורדה כקובץ טקסט</button><button class="text-button" data-go="6">עריכת הכרטיס</button></div><p class="quiet">הכרטיס כולל רק את המסלול וההחלטות. הכתיבה האישית מהשלבים הקודמים אינה נכללת.</p>`+panel(rowsHTML())+panel(`<h2>לפני שיוצאות לדרך</h2><p>שתפי את העמיתה: מה התחדד לך, מה עוד פתוח לבירור, ומה תעשי בשבוע הקרוב?</p>${field('closing','משפט לסיום, לעצמי','גיליתי ___. אקיים שיחה עם ___. מצדי אתחייב ל___.','המשפט הזה נשאר במחברת האישית ואינו נכלל בכרטיס ההחלטה.')}<p class="quiet" style="margin-top:16px">במפגש הבא נחזור לשלוש עדויות: מה הוסכם, מה התרחש בפועל ומה צריך לשנות.</p>`,'soft')+`<details class="details"><summary>לחזור לבדיקה אחרי ההתנסות</summary>${field('reviewAgreed','מה הוסכם עם המחנכת?')}${field('reviewHappened','מה התרחש בפועל?')}${field('reviewNext','מה צריך לשנות בהמשך?')}<p class="quiet">השדות האלה נשמרים במחברת האישית. מועד הבדיקה הוא לתכנון בלבד; האפליקציה אינה שולחת תזכורת.</p></details><div class="nav-actions"><button class="secondary" data-go="6">→ חזרה לעריכה</button><button class="text-button" data-action="backup">הורדת גיבוי של כל המחברת</button></div>`;}
 $('#main').innerHTML=html;
 bindInputs();save();
}
function bindInputs(){document.querySelectorAll('[data-field]').forEach(el=>el.addEventListener('input',()=>{data.fields[el.dataset.field]=el.value;save();}));}
function go(n){if(n<0||n>7)return;if(data.step===4&&n!==4)pauseTimer();data.step=n;if(n>0){data.lastStep=n;if(!data.visited.includes(n))data.visited.push(n);}save();render();$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});document.querySelector('.step-link.active')?.scrollIntoView({block:'nearest',inline:'nearest'});}
function clock(){return `${String(Math.floor(timer.left/60)).padStart(2,'0')}:${String(timer.left%60).padStart(2,'0')}`;}
function refreshClock(){if($('#clock'))$('#clock').textContent=clock();if($('#timer-toggle'))$('#timer-toggle').textContent=timer.running?'השהיה':timer.left===0?'הפעלה מחדש':'הפעלת שעון';}
function pauseTimer(){if(timer.running){timer.left=Math.max(0,Math.ceil((timer.end-Date.now())/1000));timer.running=false;}clearInterval(tickId);refreshClock();}
function toggleTimer(){if(timer.running){pauseTimer();return;}if(timer.left===0)timer.left=phases[timer.phase][1]*60;timer.running=true;timer.end=Date.now()+timer.left*1000;refreshClock();tickId=setInterval(()=>{timer.left=Math.max(0,Math.ceil((timer.end-Date.now())/1000));refreshClock();if(timer.left===0){pauseTimer();notify('הזמן לחלק הזה הסתיים. אפשר לעבור לחלק הבא כשמתאים לכן.');if($('#timer-note'))$('#timer-note').textContent='הזמן הסתיים. בחרו את החלק הבא למעלה, או הפעילו שוב.';}},250);}
function setPhase(i){pauseTimer();timer.phase=i;timer.left=phases[i][1]*60;document.querySelectorAll('[data-phase]').forEach(b=>{b.classList.toggle('active',+b.dataset.phase===i);b.setAttribute('aria-pressed',String(+b.dataset.phase===i));});$('#phase-description').textContent=phases[i][2];$('#timer-label').textContent=phases[i][0];$('#timer-note').textContent='השעון לבחירתכן. בסיום כל חלק עוברים לחלק הבא בלחיצה.';refreshClock();}
function download(filename,text,mime='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type:mime}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function exportPlan(){const r=selectedRoute();const text='מראה פנימית — כרטיס ההחלטה שלי\n\nמסלול: '+(r?r.name:'פתוח לבחירה')+'\n\n'+summaryRows().map(([l,v])=>l+'\n'+(v||'פתוח להשלמה בשיחה')).join('\n\n');download('כרטיס-החלטה.txt','\ufeff'+text);notify('כרטיס ההחלטה הוכן להורדה.');}
function printPlan(){$('#print-area').innerHTML=planHTML();const t=document.title;document.title='כרטיס-החלטה-מראה-פנימית';window.print();setTimeout(()=>{document.title=t;},1500);notify('בחלון ההדפסה בחרי ״שמירה כ־PDF״ כיעד.');}
function backup(){download('growth-notebook-backup.json',JSON.stringify({format:'growth-notebook',version:1,data},null,2),'application/json');notify('הגיבוי כולל את כל הכתיבה האישית שלך.');}
function modal(title,content){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=content;if(!$('#dialog').open)$('#dialog').showModal();}
function privacy(){modal('המחברת נשארת אצלך',`<p>התשובות נשמרות באחסון המקומי של הדפדפן במכשיר הזה. אין באפליקציה שליחה של התשובות למנחה, שיתוף בין משתתפות או סנכרון בין מכשירים.</p><p>מי שמשתמשת באותו דפדפן ובאותו מכשיר יכולה לראות את המחברת. מומלץ לכתוב בראשי תיבות. ניקוי נתוני הדפדפן עלול למחוק אותה.</p><p>כרטיס ההחלטה כולל רק את המסלול והתוכנית. גיבוי המחברת כולל גם את כל ההתבוננות האישית.</p><div class="dialog-actions"><button class="secondary" data-action="backup">הורדת גיבוי אישי</button></div>`);}
function settings(){modal('נגישות והמחברת שלי',`<div class="setting-row"><label><input type="checkbox" id="large" ${data.prefs.large?'checked':''}> הגדלת טקסט</label><label><input type="checkbox" id="contrast" ${data.prefs.contrast?'checked':''}> ניגודיות מוגברת</label></div><div class="setting-row"><h3>גיבוי והעברה למכשיר אחר</h3><p class="quiet">הגיבוי כולל את כל התשובות האישיות. שמרי אותו במקום פרטי.</p><button class="secondary" data-action="backup">הורדת גיבוי המחברת</button><label for="import-file" style="margin-top:16px">טעינת גיבוי קיים</label><input type="file" accept=".json,application/json" id="import-file"><p class="quiet">טעינה מחליפה את המחברת הנוכחית לאחר אישור.</p></div><div class="setting-row"><button class="text-button" data-action="reset">מחיקת התשובות ופתיחת תהליך חדש</button></div>`);$('#large').onchange=e=>{data.prefs.large=e.target.checked;document.body.classList.toggle('large-text',data.prefs.large);save();};$('#contrast').onchange=e=>{data.prefs.contrast=e.target.checked;document.body.classList.toggle('high-contrast',data.prefs.contrast);save();};$('#import-file').onchange=importBackup;}
async function importBackup(e){const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error();const parsed=JSON.parse(await file.text());const d=parsed.data;if(parsed.format!=='growth-notebook'||parsed.version!==1||!d||!d.fields||typeof d.fields!=='object'||Array.isArray(d.fields)||Object.values(d.fields).some(v=>typeof v!=='string')||!Number.isInteger(d.step)||d.step<0||d.step>7||typeof d.route!=='string'||(d.route&&!routes.some(r=>r.id===d.route)))throw Error();const next={step:d.step,fields:{...d.fields},route:d.route,caseType:typeof d.caseType==='string'?d.caseType:'',visited:Array.isArray(d.visited)?d.visited.filter(x=>Number.isInteger(x)&&x>=1&&x<=7):[],lastStep:Number.isInteger(d.lastStep)&&d.lastStep>=1&&d.lastStep<=7?d.lastStep:1,prefs:{large:!!d.prefs?.large,contrast:!!d.prefs?.contrast}};modal('להחליף את המחברת הנוכחית?',`<p>הגיבוי תקין. טעינתו תחליף את התשובות הנוכחיות. אפשר להוריד אותן לפני ההחלפה.</p><div class="dialog-actions"><button class="secondary" data-action="backup">גיבוי התשובות הנוכחיות</button><button class="primary" id="confirm-import">טעינת הגיבוי</button><button class="text-button" data-action="close">ביטול</button></div>`);$('#confirm-import').onclick=()=>{pauseTimer();data=next;save();$('#dialog').close();go(data.step);notify('המחברת שוחזרה מהגיבוי.');};}catch(err){notify('הקובץ אינו גיבוי תקין של המחברת. התשובות שלך לא השתנו.');e.target.value='';}}
function reset(){modal('לפתוח תהליך חדש?',`<p>כל התשובות במחברת הזאת יימחקו מהמכשיר. אפשר להוריד גיבוי אישי קודם.</p><div class="dialog-actions"><button class="secondary" data-action="backup">הורדת גיבוי</button><button class="danger" id="confirm-reset">מחיקה ופתיחת תהליך חדש</button><button class="text-button" data-action="close">ביטול</button></div>`);$('#confirm-reset').onclick=()=>{pauseTimer();data={step:0,fields:{},route:'',caseType:'',visited:[],prefs:data.prefs};timer={phase:0,left:60,running:false,end:0};save();$('#dialog').close();go(0);};}
function guide(){modal('מפת המפגש · שעה אחת',`<p>עובדות על אותו מקרה לאורך המפגש. הכתיבה אישית, והשיתוף נתון לבחירה.</p>${[['פתיחה · 6 דקות','מקרה ממשי מהחודש האחרון. מתחילות במה שנאמר ונעשה, לפני הפרשנות.'],['מפת תשומת הלב · 8 דקות','אחריות, זמן, משוב, סמכות והקלה. מסמנות ממצא אחד שקשור למקרה.'],['הדפוס שלי · 14 דקות','בזוגות, 7 דקות לכל משתתפת. מבררות מה חשוב לשמור ואיזה מידע חסר.'],['שיחה אחרת · 16 דקות','8 דקות לכל משתתפת: רקע, ניסיון, משוב, ניסיון נוסף וכתיבה. מחליפות תפקידים.'],['בחירה ותוכנית · 12 דקות','בוחרות מסלול אחד ובונות החלטה שאפשר לקיים בשבוע העבודה.'],['סיום · 4 דקות','משתפות בזוגות בבחירה ובצעד הראשון. חוזרות לבדיקה בעוד חודש.']].map(([h,p])=>`<div class="guide-stage"><strong>${h}</strong><p>${p}</p></div>`).join('')}<div class="callout">לא מנתחות אישיות של מנהלת או של מחנכת נעדרת. חוזרות לאירוע, למידע החסר ולפעולה שאפשר לשנות.</div><p class="quiet">כלי ההנחיה פותח בהשראת המהלך ״מה אני מחזיקה — ומה יכול לצמוח?״. אין אבחון או דירוג אוטומטי של התשובות.</p>`);}
document.addEventListener('click',e=>{
 const goButton=e.target.closest('[data-go]');if(goButton){go(+goButton.dataset.go);return;}
 const type=e.target.closest('[data-case]');if(type){data.caseType=type.dataset.case;save();document.querySelectorAll('[data-case]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.case===data.caseType)));return;}
 const route=e.target.closest('[data-route]');if(route){data.route=route.dataset.route;save();const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector(`[data-route="${data.route}"]`)?.focus({preventScroll:true});return;}
 const phase=e.target.closest('[data-phase]');if(phase){setPhase(+phase.dataset.phase);return;}
 if(e.target.closest('#timer-toggle')){toggleTimer();return;}if(e.target.closest('#timer-reset')){setPhase(timer.phase);return;}
 const a=e.target.closest('[data-action]')?.dataset.action;if(a==='backup')backup();if(a==='download')exportPlan();if(a==='print')printPlan();if(a==='reset')reset();if(a==='close')$('#dialog').close();
});
$('#home').onclick=e=>{e.preventDefault();go(0);};$('#guide').onclick=guide;$('#settings').onclick=settings;$('#privacy').onclick=privacy;$('#close-dialog').onclick=()=>$('#dialog').close();
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&timer.running){timer.left=Math.max(0,Math.ceil((timer.end-Date.now())/1000));refreshClock();}});
